/**
 * Fonte Caladea, embutida em base64 para uso no jsPDF (Ordem de Serviço).
 *
 * Caladea é metricamente compatível com a Cambria (mesmo espaçamento e
 * largura de caracteres, visual quase idêntico) e distribuída sob a
 * licença SIL Open Font License — ao contrário da Cambria, que é
 * proprietária da Microsoft e não pode ser redistribuída livremente
 * dentro do sistema. Fonte: pacote npm @fontsource/caladea (subconjunto
 * "latin", que cobre todos os acentos do português).
 */

import type { jsPDF } from 'jspdf';

const CALADEA_REGULAR_BASE64 =
  '';

const CALADEA_BOLD_BASE64 =
  '';

let registered = false;

/** Registra a fonte Caladea no documento — chamar antes de setFont('Caladea', ...). */
export function registerCaladeaFont(doc: jsPDF): void {
  doc.addFileToVFS('Caladea-Regular.ttf', CALADEA_REGULAR_BASE64);
  doc.addFont('Caladea-Regular.ttf', 'Caladea', 'normal');
  doc.addFileToVFS('Caladea-Bold.ttf', CALADEA_BOLD_BASE64);
  doc.addFont('Caladea-Bold.ttf', 'Caladea', 'bold');
  registered = true;
}

export const FONT_NAME = 'Caladea';
